#!/usr/bin/env node
// Bundles prompts/system.md and skills/<id>/SKILL.md into src/prompts.generated.ts
// (Workers cannot read files at runtime). Run after editing a prompt:
//   pnpm --filter @rolling/agent gen:prompts
// A test fails when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

export function renderPrompts() {
  const system = readFileSync(join(root, 'prompts/system.md'), 'utf8');
  const skills = {};
  for (const id of readdirSync(join(root, 'skills')).sort()) {
    skills[id] = readFileSync(join(root, 'skills', id, 'SKILL.md'), 'utf8');
  }
  return [
    '// Generated by scripts/gen-prompts.mjs from prompts/system.md and skills/*/SKILL.md. Do not edit.',
    `export const SYSTEM_PROMPT = ${JSON.stringify(system)};`,
    `export const SKILL_PROMPTS: Record<string, string> = ${JSON.stringify(skills, null, 2)};`,
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(join(root, 'src/prompts.generated.ts'), renderPrompts());
  console.log('wrote src/prompts.generated.ts');
}
